// The administrator's Scoring settings page.
//
// Administrators change scoring through controls, never by typing a formula: a weight for every part of every drill, the
// benchmark values ("full marks at" / "zero points at"), a choice of scoring curve, penalty cost, pace strictness, the accuracy
// needed for full marks, and for the overall ranking the method, which attempt counts, and the facet weights.
//
// While editing, the page shows (1) a live preview of exactly what the Analysis page will say about the new formulas (generated by
// formulas.js), and (2) example attempts and example drivers scored with the CURRENT (saved) settings and with the NEW (draft)
// settings side by side. The examples can be edited, added, removed, and saved for other administrators. It also shows how the
// change would affect the attempts and drivers already recorded.
//
// Saving writes settings/scoring (read by everyone, so guests' on-the-spot scores use the same rules) and settings/scoringExamples.
// Every recorded attempt is then re-scored from its raw answers with the new settings (app.js -> applyScoring()).
import { esc, now } from "./util.js";
import { FACETS } from "./constants.js";
import {
	COMPONENTS,
	CURVES,
	DEFAULT_SCORING,
	FACET_ORDER,
	OVERALL_METHODS,
	ATTEMPT_RULES,
	normalizeScoring,
	validateScoring,
	scoreSubmission,
	driverSummary,
} from "./scoring.js";
import { facetCard, overallCard, bandsTableHtml, changesFromDefault, FACET_NAMES, fmt } from "./formulas.js";

const clone = (value) => JSON.parse(JSON.stringify(value));
const two = (n) => (Number.isFinite(Number(n)) ? Number(n).toFixed(2) : "--");
const TABS = [["overall", "General statistics"], ...FACET_ORDER.map((k) => [k, FACET_NAMES[k]])];
const SHORT = { speed: "Speed", defense: "Defense", offense: "Offense", shooting: "Shooting" };

// ---------------------------------------------------------------- example data
// The raw answers each drill's score reads (the numeric questions on the built-in forms).
const exampleFields = (facet) => FACETS[facet].fields.filter((f) => f[2] === "number").map((f) => ({ key: f[0], label: f[6] || f[1] }));
export const DEFAULT_EXAMPLES = {
	facets: {
		speed: [
			{ label: "Fast and clean", totalTime: 16, lap1: 8, lap2: 8, penalties: 0 },
			{ label: "Fast, uneven laps", totalTime: 17, lap1: 6, lap2: 11, penalties: 1 },
			{ label: "Middle of the pack", totalTime: 22.5, lap1: 11, lap2: 11.5, penalties: 2 },
			{ label: "Slow but careful", totalTime: 29, lap1: 14, lap2: 15, penalties: 0 },
			{ label: "Fast, many penalties", totalTime: 18, lap1: 9, lap2: 9, penalties: 5 },
		],
		defense: [
			{ label: "Excellent defender", scorePreventions: 6, fuelPreventions: 4, secondsWasted: 30 },
			{ label: "Solid defender", scorePreventions: 3, fuelPreventions: 2, secondsWasted: 15 },
			{ label: "Rarely engaged", scorePreventions: 1, fuelPreventions: 0, secondsWasted: 5 },
			{ label: "Blocks scoring only", scorePreventions: 8, fuelPreventions: 1, secondsWasted: 20 },
			{ label: "Wastes time well", scorePreventions: 2, fuelPreventions: 5, secondsWasted: 40 },
		],
		offense: [
			{ label: "Benchmark run", fuelShot: 30, fuelScored: 20, evasions: 5 },
			{ label: "Accurate, few evasions", fuelShot: 20, fuelScored: 18, evasions: 2 },
			{ label: "High volume, inaccurate", fuelShot: 40, fuelScored: 10, evasions: 3 },
			{ label: "Great evader", fuelShot: 10, fuelScored: 8, evasions: 6 },
			{ label: "Shut down", fuelShot: 5, fuelScored: 1, evasions: 0 },
		],
		shooting: [
			{ label: "Benchmark run", fuelShot: 30, fuelScored: 20, penalties: 0 },
			{ label: "Accurate, lower volume", fuelShot: 20, fuelScored: 18, penalties: 1 },
			{ label: "High volume, inaccurate", fuelShot: 40, fuelScored: 15, penalties: 0 },
			{ label: "Careful, few shots", fuelShot: 12, fuelScored: 10, penalties: 3 },
			{ label: "Struggling", fuelShot: 25, fuelScored: 5, penalties: 0 },
		],
	},
	// Example drivers for the overall ranking: facet scores out of 10, oldest attempt first, separated by commas (blank = not done).
	overall: [
		{ label: "Driver A (one perfect facet)", speed: "10", defense: "", offense: "", shooting: "" },
		{ label: "Driver B (well-rounded)", speed: "6", defense: "6", offense: "6", shooting: "6" },
		{ label: "Improving driver", speed: "4, 7", defense: "5, 8", offense: "6", shooting: "" },
		{ label: "Specialist", speed: "9.5", defense: "", offense: "", shooting: "9" },
		{ label: "Inconsistent driver", speed: "9, 3", defense: "8, 4", offense: "7, 2", shooting: "6, 6" },
	],
};
function normalizeExamples(saved) {
	const out = clone(DEFAULT_EXAMPLES);
	if (!saved || typeof saved !== "object") return out;
	for (const facet of FACET_ORDER) if (Array.isArray(saved.facets?.[facet])) out.facets[facet] = clone(saved.facets[facet]);
	if (Array.isArray(saved.overall)) out.overall = clone(saved.overall);
	return out;
}
// "4, 7" -> [4, 7] (each limited to 0-10); blank -> []
const parseScores = (text) =>
	String(text ?? "")
		.split(/[,;\s]+/)
		.map((x) => x.trim())
		.filter((x) => x !== "" && Number.isFinite(Number(x)))
		.map((x) => Math.max(0, Math.min(10, Number(x))));
// An example driver as the attempt list driverSummary() expects (createdAt increases left to right, so the last one is the most recent).
function exampleAttempts(row) {
	const subs = [];
	let n = 0;
	for (const facet of FACET_ORDER)
		parseScores(row[facet]).forEach((score) =>
			subs.push({ facet, createdAt: new Date(Date.UTC(2026, 0, 1, 0, 0, n++)).toISOString(), score: { final: score } }),
		);
	return subs;
}
// Standard competition ranking (1, 2, 2, 4) by score, highest first.
const ranks = (values) => values.map((v) => 1 + values.filter((x) => x > v).length);

// ---------------------------------------------------------------- state helpers
function ensureDraft(ctx) {
	const { state } = ctx;
	if (!state.scoringDraft) {
		state.scoringDraft = clone(state.scoring);
		state.scoringExamples = normalizeExamples(state.data.settings?.scoringExamples);
		state.scoringSavedExamples = clone(state.scoringExamples);
		state.scoringDirty = false;
	}
	state.scoringTab ??= "overall";
	return state.scoringDraft;
}
export function scoringIsDirty(state) {
	return Boolean(state.scoringDraft && state.scoringDirty);
}
export function resetScoringDraft(state) {
	state.scoringDraft = null;
	state.scoringDirty = false;
}
// The draft as a usable settings object, or null while it has problems (then the preview and "New" columns are not shown).
const usable = (draft) => (validateScoring(draft).length ? null : normalizeScoring(draft));
const getPath = (o, path) => path.split(".").reduce((x, k) => x?.[k], o);
function setPath(o, path, value) {
	const keys = path.split(".");
	const last = keys.pop();
	keys.reduce((x, k) => x[k], o)[last] = value;
}

// ---------------------------------------------------------------- rendering
const numberInput = (path, value, { min = 0, max = "", step = "any", label = "" } = {}) =>
	`<input type="number" data-sc="${path}" value="${esc(value)}" min="${min}" ${max !== "" ? `max="${max}"` : ""} step="${step}" inputmode="decimal" aria-label="${esc(label)}" />`;
function weightControl(path, value, label) {
	return `<div class="sc-weight"><span class="sc-weight-label">Weight</span><input type="range" min="0" max="100" step="1" data-sc="${path}" value="${esc(value)}" aria-label="${esc(label)} weight (slider)" />${numberInput(path, value, { min: 0, max: 100, step: "any", label: `${label} weight (percent)` })}<span class="sc-unit">%</span></div>`;
}
const totalHtml = (total) => {
	const ok = Math.abs(total - 100) < 0.001;
	return `<span class="sc-total ${ok ? "ok" : "bad"}">Total: ${fmt(total)}%${ok ? " ✓" : " (must be 100%)"}</span>`;
};
function componentEditor(facet, c, s) {
	const base = `facets.${facet}.${c.key}`;
	let body = "";
	if (c.kind === "range") {
		const time = c.unit === "s" && facet === "speed";
		body = `<div class="sc-grid"><label class="b-field"><span>Full marks (10) at</span>${numberInput(`${base}.full`, s.full, { label: `${c.label} full marks` })}<small class="help">${time ? "The excellent time, in seconds." : `This many ${esc(c.unitWord)} or more earns 10.`}</small></label><label class="b-field"><span>Zero points at</span>${numberInput(`${base}.zero`, s.zero, { label: `${c.label} zero points` })}<small class="help">${time ? "The slow cutoff, in seconds." : "Usually 0."}</small></label><label class="b-field sc-wide"><span>Scoring curve</span><select data-sc="${base}.curve">${Object.entries(CURVES)
			.map(([k, x]) => `<option value="${k}" ${s.curve === k ? "selected" : ""}>${esc(x.label)}</option>`)
			.join("")}</select></label></div>`;
	} else if (c.kind === "pace")
		body = `<div class="sc-grid"><label class="b-field sc-wide"><span>Strictness</span>${numberInput(`${base}.strictness`, s.strictness, { min: 0, max: 10, step: "0.1", label: "Pace strictness" })}<small class="help">1 is the original rule (a lap twice as long as the other scores 5). 2 is twice as strict; 0 ignores lap consistency.</small></label></div>`;
	else if (c.kind === "penalty")
		body = `<div class="sc-grid"><label class="b-field sc-wide"><span>Points lost per penalty</span>${numberInput(`${base}.perPenalty`, s.perPenalty, { min: 0, max: 10, step: "0.5", label: `${c.label} points per penalty` })}<small class="help">This part starts at 10 and loses this many points for every penalty.</small></label></div>`;
	else
		body = `<div class="sc-grid"><label class="b-field sc-wide"><span>Accuracy for full marks (%)</span>${numberInput(`${base}.target`, s.target, { min: 1, max: 100, step: "any", label: "Accuracy for full marks" })}<small class="help">100 means only perfect shooting earns 10. 80 means 80% accuracy or better earns 10.</small></label></div>`;
	return `<div class="sc-comp"><div class="sc-comp-head"><strong>${esc(c.label)}</strong><span class="sc-symbol">${esc(c.symbol)}</span></div>${weightControl(`${base}.weight`, s.weight, c.label)}${body}</div>`;
}
function facetSettingsHtml(facet, draft) {
	const total = COMPONENTS[facet].reduce((t, c) => t + (Number(draft.facets[facet][c.key].weight) || 0), 0);
	return `<div class="panel-heading"><div><h3>${esc(FACET_NAMES[facet])} score</h3><p>Each part is scored out of 10; the weights decide how much each part counts in the final score.</p></div></div><div class="sc-body">${COMPONENTS[facet]
		.map((c) => componentEditor(facet, c, draft.facets[facet][c.key]))
		.join("")}<div class="sc-total-row" id="sc-total">${totalHtml(total)}<button type="button" class="button button-secondary button-small" data-sc-balance="facets.${facet}">Make weights add up to 100%</button><button type="button" class="button button-secondary button-small" data-sc-default="${facet}">Use original ${esc(SHORT[facet])} settings</button></div></div>`;
}
function overallSettingsHtml(draft) {
	const o = draft.overall;
	const total = FACET_ORDER.reduce((t, k) => t + (Number(o.weights[k]) || 0), 0);
	return `<div class="panel-heading"><div><h3>Overall ranking (General statistics)</h3><p>How the four facet scores become each driver's overall score on the leaderboard.</p></div></div><div class="sc-body">
  <fieldset class="sc-methods"><legend>Ranking method</legend>${Object.entries(OVERALL_METHODS)
		.map(
			([k, m]) =>
				`<label class="sc-method ${o.method === k ? "selected" : ""}"><input type="radio" name="sc-method" data-sc="overall.method" value="${k}" ${o.method === k ? "checked" : ""} /><span><strong>${esc(m.label)}</strong><small>${esc(m.help)}</small></span></label>`,
		)
		.join("")}</fieldset>
  <label class="b-field"><span>Which attempt counts in each facet</span><select data-sc="overall.attempt">${Object.entries(ATTEMPT_RULES)
		.map(([k, r]) => `<option value="${k}" ${o.attempt === k ? "selected" : ""}>${esc(r.label)}</option>`)
		.join("")}</select><small class="help">The original rule uses each driver's most recent attempt, so improvement shows straight away.</small></label>
  <div class="sc-comp"><div class="sc-comp-head"><strong>Facet weights</strong></div><p class="help" style="margin:0 0 10px">How much each facet counts in the facet average${o.method === "missingZero" ? " (here: in the weighted sum)" : ""}. 25% each treats all facets equally.</p>${FACET_ORDER.map(
		(k) => `<div class="sc-facet-weight"><span>${esc(FACET_NAMES[k])}</span>${weightControl(`overall.weights.${k}`, o.weights[k], FACET_NAMES[k])}</div>`,
	).join("")}</div>
  <div class="sc-total-row" id="sc-total">${totalHtml(total)}<button type="button" class="button button-secondary button-small" data-sc-balance="overall.weights">Make weights add up to 100%</button><button type="button" class="button button-secondary button-small" data-sc-default="overall">Use original overall settings</button></div>
</div>`;
}
function previewHtml(state) {
	const cfg = usable(state.scoringDraft);
	if (!cfg) return `<p class="notice">Fix the problems listed at the top of the page to see the preview.</p>`;
	const tab = state.scoringTab;
	const changes = changesFromDefault(cfg);
	const changed = changes.length
		? `<div class="eq-changes"><p><strong>Differences from the original DriveLab scoring</strong> (listed on the Analysis page):</p><ul>${changes.map((c) => `<li>${esc(c)}</li>`).join("")}</ul></div>`
		: `<p class="eq-note">These are the original DriveLab scoring settings.</p>`;
	return `${changed}${tab === "overall" ? `${overallCard(cfg)}<h4 class="sc-sub">Possible overall score by facets completed</h4>${bandsTableHtml(cfg)}` : facetCard(tab, FACET_NAMES[tab], cfg)}`;
}

// Example attempts for one drill: raw answers (editable), each part's new score, and the final score now vs. with the draft.
function facetExamplesHtml(state, facet) {
	const fields = exampleFields(facet);
	const rows = state.scoringExamples.facets[facet];
	const comps = COMPONENTS[facet];
	return `<div class="table-wrap sc-table"><table><thead><tr><th>Example</th>${fields.map((f) => `<th class="sc-in">${esc(f.label)}</th>`).join("")}${comps.map((c) => `<th class="sc-part" title="${esc(c.label)} (new settings)">${esc(c.symbol)}</th>`).join("")}<th>Current score</th><th>New score</th><th>Change</th><th class="no-print"><span class="sr-only">Remove</span></th></tr></thead><tbody>${
		rows
			.map(
				(r, i) =>
					`<tr><td><input class="sc-label-input" data-ex="facets.${facet}.${i}.label" value="${esc(r.label)}" aria-label="Example name" /></td>${fields
						.map((f) => `<td class="sc-in"><input type="number" min="0" step="any" inputmode="decimal" data-ex="facets.${facet}.${i}.${f.key}" value="${esc(r[f.key] ?? "")}" aria-label="${esc(f.label)}" /></td>`)
						.join("")}${comps.map((c) => `<td class="sc-part-val" data-r="${i}-${c.key}"></td>`).join("")}<td data-r="${i}-before"></td><td class="sc-new" data-r="${i}-after"></td><td data-r="${i}-delta"></td><td class="no-print"><button type="button" class="icon-btn danger" data-ex-remove="${i}" title="Remove this example" aria-label="Remove this example">×</button></td></tr>`,
			)
			.join("") || `<tr><td colspan="${fields.length + comps.length + 5}" class="empty">No examples. Press Add example.</td></tr>`
	}</tbody></table></div><p class="help sc-legend">${comps.map((c) => `<strong>${esc(c.symbol)}</strong> = ${esc(c.label)}`).join(" · ")} (each part out of 10, with the new settings).</p>`;
}
function overallExamplesHtml(state) {
	const rows = state.scoringExamples.overall;
	return `<div class="table-wrap sc-table"><table><thead><tr><th>Example driver</th>${FACET_ORDER.map((k) => `<th class="sc-in">${SHORT[k]}</th>`).join("")}<th>Facets</th><th>Current overall</th><th>Current rank</th><th>New overall</th><th>New rank</th><th>Change</th><th class="no-print"><span class="sr-only">Remove</span></th></tr></thead><tbody>${
		rows
			.map(
				(r, i) =>
					`<tr><td><input class="sc-label-input" data-ex="overall.${i}.label" value="${esc(r.label)}" aria-label="Example driver name" /></td>${FACET_ORDER.map(
						(k) => `<td class="sc-in"><input data-ex="overall.${i}.${k}" value="${esc(r[k] ?? "")}" placeholder="--" inputmode="decimal" aria-label="${SHORT[k]} scores" /></td>`,
					).join("")}${["facets", "before", "brank"].map((k) => `<td data-r="${i}-${k}"></td>`).join("")}<td class="sc-new" data-r="${i}-after"></td><td data-r="${i}-arank"></td><td data-r="${i}-delta"></td><td class="no-print"><button type="button" class="icon-btn danger" data-ex-remove="${i}" title="Remove this example" aria-label="Remove this example">×</button></td></tr>`,
			)
			.join("") || `<tr><td colspan="12" class="empty">No examples. Press Add example.</td></tr>`
	}</tbody></table></div><p class="help sc-legend">Enter each facet's scores out of 10, oldest first, separated by commas (for example <code>4, 7</code>). Leave a box blank if the driver has not done that facet. Ranks compare the example drivers with each other.</p>`;
}
const changeCell = (before, after) => {
	if (!Number.isFinite(after) || !Number.isFinite(before)) return `<span class="sc-delta">--</span>`;
	const d = Math.round((after - before) * 100) / 100;
	return `<span class="sc-delta ${d > 0 ? "up" : d < 0 ? "down" : ""}">${d > 0 ? "+" : ""}${d.toFixed(2)}</span>`;
};
const rankCell = (before, after) => {
	if (!after) return "--";
	const d = before - after;
	return `#${after}${d ? ` <small class="sc-delta ${d > 0 ? "up" : "down"}">${d > 0 ? "▲" : "▼"}${Math.abs(d)}</small>` : ""}`;
};
// Fills in every result cell of the example table (inputs are left untouched, so typing never loses focus).
function refreshExampleResults(state) {
	const tab = state.scoringTab,
		saved = state.scoring,
		next = usable(state.scoringDraft);
	const put = (key, html) => {
		const cell = document.querySelector(`[data-r="${key}"]`);
		if (cell) cell.innerHTML = html;
	};
	if (tab === "overall") {
		const rows = state.scoringExamples.overall;
		const before = rows.map((r) => driverSummary(exampleAttempts(r), saved));
		const after = rows.map((r) => (next ? driverSummary(exampleAttempts(r), next) : null));
		const rb = ranks(before.map((x) => (x.completed ? x.overall : -1)));
		const ra = next ? ranks(after.map((x) => (x.completed ? x.overall : -1))) : [];
		rows.forEach((_, i) => {
			const b = before[i],
				a = after[i];
			put(`${i}-facets`, `${b.completed}/4`);
			put(`${i}-before`, b.completed ? two(b.overall) : "--");
			put(`${i}-brank`, b.completed ? `#${rb[i]}` : "--");
			put(`${i}-after`, a && a.completed ? `<strong>${two(a.overall)}</strong>` : "--");
			put(`${i}-arank`, a && a.completed ? rankCell(rb[i], ra[i]) : "--");
			put(`${i}-delta`, a && b.completed ? changeCell(b.overall, a.overall) : "--");
		});
		return;
	}
	state.scoringExamples.facets[tab].forEach((r, i) => {
		const sub = { facet: tab, data: r };
		const b = scoreSubmission(sub, saved);
		const a = next ? scoreSubmission(sub, next) : null;
		COMPONENTS[tab].forEach((c) => put(`${i}-${c.key}`, a ? two(a[c.key]) : "--"));
		put(`${i}-before`, two(b.final));
		put(`${i}-after`, a ? `<strong>${two(a.final)}</strong>` : "--");
		put(`${i}-delta`, a ? changeCell(b.final, a.final) : "--");
	});
}
// How the change would affect what is already recorded.
function impactHtml(state) {
	const next = usable(state.scoringDraft);
	const built = state.data.submissions.filter((x) => FACET_ORDER.includes(x.facet));
	if (!built.length) return `<p class="help">No attempts have been recorded yet, so only the examples above are affected.</p>`;
	if (!next) return `<p class="help">Fix the problems listed at the top of the page to see the effect on recorded attempts.</p>`;
	const rescore = (cfg) => built.map((x) => ({ ...x, score: scoreSubmission(x, cfg) }));
	const before = rescore(state.scoring),
		after = rescore(next);
	if (state.scoringTab !== "overall") {
		const f = state.scoringTab;
		const b = before.filter((x) => x.facet === f),
			a = after.filter((x) => x.facet === f);
		if (!b.length) return `<p class="help">No ${esc(FACET_NAMES[f])} attempts have been recorded yet.</p>`;
		const avg = (l) => l.reduce((t, x) => t + x.score.final, 0) / l.length;
		const moved = b.filter((x, i) => Math.abs(x.score.final - a[i].score.final) >= 0.005).length;
		return `<p class="sc-impact">Across the <strong>${b.length}</strong> recorded ${esc(FACET_NAMES[f])} attempt${b.length === 1 ? "" : "s"}, the average score would go from <strong>${two(avg(b))}</strong> to <strong>${two(avg(a))}</strong>; ${moved} attempt${moved === 1 ? "" : "s"} would change.</p>`;
	}
	const board = (subs, cfg) => {
		const by = {};
		subs.forEach((x) => (by[x.driverName] ??= []).push(x));
		const rows = Object.entries(by).map(([name, list]) => ({ name, ...driverSummary(list, cfg) }));
		const r = ranks(rows.map((x) => x.overall));
		return Object.fromEntries(rows.map((x, i) => [x.name, { ...x, rank: r[i] }]));
	};
	const b = board(before, state.scoring),
		a = board(after, next);
	const names = Object.keys(a).sort((x, y) => a[x].rank - a[y].rank || x.localeCompare(y));
	const moved = names.filter((n) => a[n].rank !== b[n].rank).length;
	return `<p class="sc-impact">${names.length} recorded driver${names.length === 1 ? "" : "s"}; ${moved} would change rank.</p><div class="table-wrap sc-table" style="max-height:360px"><table><thead><tr><th>Driver</th><th>Facets</th><th>Current overall</th><th>Current rank</th><th>New overall</th><th>New rank</th><th>Change</th></tr></thead><tbody>${names
		.map(
			(n) =>
				`<tr><td><strong>${esc(n)}</strong></td><td>${a[n].completed}/4</td><td>${two(b[n].overall)}</td><td>#${b[n].rank}</td><td><strong>${two(a[n].overall)}</strong></td><td>${rankCell(b[n].rank, a[n].rank)}</td><td>${changeCell(b[n].overall, a[n].overall)}</td></tr>`,
		)
		.join("")}</tbody></table></div>`;
}

export function renderScoringEditor(ctx) {
	const { state } = ctx;
	const draft = ensureDraft(ctx);
	const tab = state.scoringTab;
	const actions = `<div class="hero-actions sc-actions"><span id="sc-dirty" class="sc-dirty" ${state.scoringDirty ? "" : "hidden"}>Unsaved changes</span><button class="button button-secondary" id="sc-restore" type="button">Restore all original scoring</button><button class="button button-secondary" id="sc-discard" type="button">Discard changes</button><button class="button" id="sc-save" type="button">Save scoring settings</button></div>`;
	return `${ctx.pageHeader("Scoring settings", "Choose how each drill and the overall ranking are scored. Saving re-scores every recorded attempt from its raw answers, and the Analysis page explains the new formulas automatically.", actions)}
<div id="sc-errors"></div>
<div class="sc-tabs" role="tablist">${TABS.map(([k, label]) => `<button type="button" role="tab" class="sc-tab ${tab === k ? "active" : ""}" aria-selected="${tab === k}" data-sc-tab="${k}">${esc(label)}</button>`).join("")}</div>
<div class="sc-layout">
  <section class="panel sc-settings" id="sc-settings">${tab === "overall" ? overallSettingsHtml(draft) : facetSettingsHtml(tab, draft)}</section>
  <section class="panel sc-preview"><div class="panel-heading"><div><h3>Live preview of the Analysis page</h3><p>Generated automatically from the settings on the left. This is the explanation administrators will see on the Analysis page after saving.</p></div></div><div class="eq-body" id="sc-preview">${previewHtml(state)}</div></section>
</div>
<section class="panel sc-examples"><div class="panel-heading"><div><h3>${tab === "overall" ? "Example drivers" : `Example ${esc(FACET_NAMES[tab])} attempts`}</h3><p><strong>Current</strong> uses the saved settings; <strong>New</strong> uses the settings on this page. Edit any example, or add your own, to see how the change affects scores.</p></div><div class="item-actions"><button type="button" class="button button-secondary button-small" id="ex-add">Add example</button><button type="button" class="button button-secondary button-small" id="ex-reset">Reset examples</button></div></div><div class="sc-examples-body">${tab === "overall" ? overallExamplesHtml(state) : facetExamplesHtml(state, tab)}</div></section>
<section class="panel sc-examples"><div class="panel-heading"><div><h3>Effect on recorded ${tab === "overall" ? "drivers" : "attempts"}</h3><p>${tab === "overall" ? "The real leaderboard re-scored with the settings on this page (all drills and the overall ranking)." : "The real attempts for this drill, re-scored with the settings on this page."}</p></div></div><div class="sc-examples-body" id="sc-impact">${impactHtml(state)}</div></section>`;
}

export function bindScoringEditor(ctx) {
	const { state, store, toast } = ctx;
	ensureDraft(ctx);
	const dirtyBadge = document.querySelector("#sc-dirty");
	const markDirty = () => {
		state.scoringDirty = true;
		dirtyBadge.hidden = false;
	};
	const showErrors = () => {
		const problems = validateScoring(state.scoringDraft);
		document.querySelector("#sc-errors").innerHTML = problems.length
			? `<div class="notice error"><strong>Fix these before saving:</strong><ul>${problems.map((p) => `<li>${esc(p)}</li>`).join("")}</ul></div>`
			: "";
		return problems;
	};
	// Everything that depends on the draft, redrawn without touching the inputs being typed in.
	const refresh = () => {
		showErrors();
		const total =
			state.scoringTab === "overall"
				? FACET_ORDER.reduce((t, k) => t + (Number(state.scoringDraft.overall.weights[k]) || 0), 0)
				: COMPONENTS[state.scoringTab].reduce((t, c) => t + (Number(state.scoringDraft.facets[state.scoringTab][c.key].weight) || 0), 0);
		const totalBox = document.querySelector("#sc-total .sc-total");
		if (totalBox) totalBox.outerHTML = totalHtml(total);
		document.querySelector("#sc-preview").innerHTML = previewHtml(state);
		document.querySelector("#sc-impact").innerHTML = impactHtml(state);
		refreshExampleResults(state);
	};
	const redraw = () => {
		const y = window.scrollY;
		ctx.render();
		window.scrollTo(0, y);
	};

	// Settings inputs: write straight into the draft. The slider and the number box for the same weight mirror each other.
	const settings = document.querySelector("#sc-settings");
	const onSetting = (e) => {
		const el = e.target.closest("[data-sc]");
		if (!el) return;
		const path = el.dataset.sc;
		const textual = path.endsWith(".curve") || path === "overall.method" || path === "overall.attempt";
		const value = textual ? el.value : el.value === "" ? "" : Number(el.value);
		setPath(state.scoringDraft, path, value);
		settings.querySelectorAll(`[data-sc="${path}"]`).forEach((other) => {
			if (other !== el && other.type !== "radio") other.value = el.value;
		});
		if (path === "overall.method") settings.querySelectorAll(".sc-method").forEach((m) => m.classList.toggle("selected", m.querySelector("input").checked));
		markDirty();
		refresh();
	};
	settings.addEventListener("input", onSetting);
	settings.addEventListener("change", onSetting);
	// "Make weights add up to 100%": scale the current weights proportionally (equal split if they are all 0).
	settings.querySelectorAll("[data-sc-balance]").forEach(
		(b) =>
			(b.onclick = () => {
				const path = b.dataset.scBalance;
				const group = getPath(state.scoringDraft, path);
				const flat = path === "overall.weights"; // { speed: 25, ... } rather than { time: { weight: 70 }, ... }
				const keys = Object.keys(group);
				const read = (k) => Number(flat ? group[k] : group[k].weight) || 0;
				const write = (k, value) => (flat ? (group[k] = value) : (group[k].weight = value));
				const total = keys.reduce((t, k) => t + read(k), 0);
				const values = keys.map((k) => Math.round((total > 0 ? (read(k) * 100) / total : 100 / keys.length) * 10) / 10);
				// Rounding can leave the total at 99.9 or 100.1; the largest weight absorbs the difference.
				const biggest = values.indexOf(Math.max(...values));
				values[biggest] = Math.round((values[biggest] + 100 - values.reduce((a, x) => a + x, 0)) * 10) / 10;
				keys.forEach((k, i) => write(k, values[i]));
				markDirty();
				redraw();
			}),
	);
	settings.querySelectorAll("[data-sc-default]").forEach(
		(b) =>
			(b.onclick = () => {
				const k = b.dataset.scDefault;
				if (k === "overall") state.scoringDraft.overall = clone(DEFAULT_SCORING.overall);
				else state.scoringDraft.facets[k] = clone(DEFAULT_SCORING.facets[k]);
				markDirty();
				redraw();
			}),
	);

	document.querySelectorAll("[data-sc-tab]").forEach(
		(b) =>
			(b.onclick = () => {
				state.scoringTab = b.dataset.scTab;
				redraw();
			}),
	);

	// Examples: editing changes only the result cells; adding / removing redraws the page.
	const examples = state.scoringExamples;
	document.querySelectorAll("[data-ex]").forEach((input) =>
		input.addEventListener("input", () => {
			const path = input.dataset.ex;
			const numeric = input.type === "number";
			setPath(examples, path, numeric ? (input.value === "" ? "" : Number(input.value)) : input.value);
			markDirty();
			refreshExampleResults(state);
		}),
	);
	document.querySelectorAll("[data-ex-remove]").forEach(
		(b) =>
			(b.onclick = () => {
				const list = state.scoringTab === "overall" ? examples.overall : examples.facets[state.scoringTab];
				list.splice(Number(b.dataset.exRemove), 1);
				markDirty();
				redraw();
			}),
	);
	document.querySelector("#ex-add").onclick = () => {
		if (state.scoringTab === "overall")
			examples.overall.push({ label: `Example driver ${examples.overall.length + 1}`, speed: "", defense: "", offense: "", shooting: "" });
		else {
			const row = { label: `Example ${examples.facets[state.scoringTab].length + 1}` };
			exampleFields(state.scoringTab).forEach((f) => (row[f.key] = 0));
			examples.facets[state.scoringTab].push(row);
		}
		markDirty();
		redraw();
		const inputs = document.querySelectorAll(".sc-label-input");
		inputs[inputs.length - 1]?.select();
	};
	document.querySelector("#ex-reset").onclick = () => {
		if (state.scoringTab === "overall") examples.overall = clone(DEFAULT_EXAMPLES.overall);
		else examples.facets[state.scoringTab] = clone(DEFAULT_EXAMPLES.facets[state.scoringTab]);
		markDirty();
		redraw();
	};

	// Page actions.
	document.querySelector("#sc-restore").onclick = () => {
		if (!confirm("Put every drill and the overall ranking back to the original DriveLab scoring? Nothing is saved until you press Save scoring settings.")) return;
		state.scoringDraft = clone(DEFAULT_SCORING);
		markDirty();
		redraw();
	};
	document.querySelector("#sc-discard").onclick = () => {
		if (state.scoringDirty && !confirm("Discard all unsaved changes on this page?")) return;
		state.scoringDraft = clone(state.scoring);
		state.scoringExamples = clone(state.scoringSavedExamples);
		state.scoringDirty = false;
		redraw();
	};
	document.querySelector("#sc-save").onclick = async (e) => {
		if (showErrors().length) {
			window.scrollTo({ top: 0, behavior: "smooth" });
			toast("Fix the problems listed at the top before saving.");
			return;
		}
		const button = e.currentTarget;
		button.disabled = true;
		const cfg = { ...normalizeScoring(state.scoringDraft), updatedAt: now() };
		try {
			await store.saveSetting("scoring", cfg);
			await store.saveSetting("scoringExamples", examples);
		} catch (err) {
			button.disabled = false;
			toast(`Could not save the scoring settings: ${err.message}`);
			return;
		}
		state.data.settings = { ...(state.data.settings || {}), scoring: cfg, scoringExamples: clone(examples) };
		ctx.applyScoring(cfg);
		state.scoringDraft = clone(state.scoring);
		state.scoringSavedExamples = clone(examples);
		state.scoringDirty = false;
		redraw();
		toast("Scoring settings saved. Every recorded attempt has been re-scored.");
	};

	refresh();
}
